using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using EchoSphere.Core;using EchoSphere.Runtime;using EchoSphere.Presentation;
public static class CampaignArtifactAcceptance {public static object Main(){
const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;var r=UnityEngine.Object.FindAnyObjectByType<EchoSphereRuntime>();var t=r.GetType();var owned=(List<string>)t.GetField("_ownedArtifacts",F).GetValue(r);var before=owned.ToArray();object policy=t.GetField("_runEconomy",F).GetValue(r);int checks=0;var oldSection=t.GetField("_knowledgeSection",F).GetValue(r);var oldQuery=t.GetField("_knowledgeQuery",F).GetValue(r);
void Check(bool value,string why){checks++;if(!value)throw new Exception(why);}
try{t.GetField("_runEconomy",F).SetValue(r,RunEconomyRules.Create(1));var newItems=ArtifactRewardRules.Catalog(true).Where(x=>!ArtifactRewardRules.All.Contains(x)).ToArray();Check(newItems.Length==8,"eight campaign items");
foreach(var item in newItems){owned.Clear();owned.Add(item.Id);var card=NativeRunCatalog.Instance.GetArtifact(item.Id);Check(card!=null&&card.Name(true)==item.NameRussian&&card.Description(false)==item.DescriptionEnglish,"RU/EN projected card "+item.Id);foreach(var effect in item.Effects){float actual=(float)t.GetMethod("GetRunArtifactEffectTotal",F).Invoke(r,new object[]{effect.Key});Check(Math.Abs(actual-effect.Value)<.0001,"effect adapter "+item.Id+"/"+effect.Key);}}
owned.Clear();owned.AddRange(ArtifactRewardRules.All.Select(x=>x.Id));var choices=ArtifactRewardRules.PickChoices(owned,()=>0f,false,20,true);Check(choices.Count==8&&choices.Select(x=>x.Id).Distinct().Count()==8,"modern reward offers");Check(ArtifactRewardRules.PickChoices(owned,()=>0f,false,20).Count==0,"legacy reward isolation");t.GetField("_knowledgeSection",F).SetValue(r,"artifacts");t.GetField("_knowledgeQuery",F).SetValue(r,"");var archive=t.GetMethod("ReadNativeArchiveState",F).Invoke(r,null);var cards=(System.Collections.IEnumerable)archive.GetType().GetField("Cards").GetValue(archive);int count=0;foreach(var card in cards)count++;Check(count==90,"archive contains ninety artifact cards");
var result=new{result="PASS",checks,scope="Eight campaign artifact definitions,actual native RU/EN cards,runtime effect adapter,reward reachability and legacy pool isolation;no prefs write"};File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../Library/campaign-artifact-acceptance.json")),Newtonsoft.Json.JsonConvert.SerializeObject(result));return result;
}finally{t.GetField("_knowledgeSection",F).SetValue(r,oldSection);t.GetField("_knowledgeQuery",F).SetValue(r,oldQuery);owned.Clear();owned.AddRange(before);t.GetField("_runEconomy",F).SetValue(r,policy);}}}
